#!/usr/bin/env bash
# ============================================================================
# RESUME EXP15 AND EXP14 TO EPOCH 8, THEN EVALUATE BOTH
#
# Default order:
#   1. Exp15 (R2-offline + weak stable SIGReg)
#   2. Exp14 (R2-offline without SIGReg)
#   3. R2-aware evaluation of both epoch-8 checkpoints
#
# Safety:
#   - searches checkpoint.pt and checkpoint_epoch_*.pt;
#   - verifies candidates can be loaded by torch;
#   - resumes from the highest valid saved epoch/global step;
#   - refuses to silently restart from scratch if no checkpoint is found;
#   - skips training if a readable epoch-8 checkpoint already exists;
#   - evaluates only after both experiments reach at least epoch 8.
#
# This script embeds the required trainer and evaluator.
# ============================================================================

set -euo pipefail

ROOT_DIR="${ROOT_DIR:-/home/jovyan/smac-jepa-wm}"
cd "$ROOT_DIR"

TARGET_EPOCH="${TARGET_EPOCH:-8}"

EXP15_DIR="${EXP15_DIR:-runs/rnn_seqmem_exp15_r2offline_sigreg_full_h5}"
EXP14_DIR="${EXP14_DIR:-runs/rnn_seqmem_exp14_r2offline_full_h5}"

EVAL_OUT_DIR="${EVAL_OUT_DIR:-runs/eval_exp14_exp15_r2aware_epoch008}"
EVAL_MAX_BATCHES="${EVAL_MAX_BATCHES:-500}"
DIAGNOSTIC_MAX_BATCHES="${DIAGNOSTIC_MAX_BATCHES:-100}"
PROBE_EPOCHS="${PROBE_EPOCHS:-20}"
PROBE_MAX_BATCHES="${PROBE_MAX_BATCHES:-300}"
PROBE_SAMPLES_PER_EPOCH="${PROBE_SAMPLES_PER_EPOCH:-20000}"
EVAL_BATCH_SIZE="${EVAL_BATCH_SIZE:-16}"
EVAL_NUM_WORKERS="${EVAL_NUM_WORKERS:-4}"
FORCE_RETRAIN_PROBE="${FORCE_RETRAIN_PROBE:-0}"

STAMP="$(date +%Y%m%d_%H%M%S)"
LOG_DIR="runs/resume_exp14_exp15_to_e8_logs_${STAMP}"
TMP_DIR="$(mktemp -d)"

cleanup() {
  rm -rf "$TMP_DIR"
}
trap cleanup EXIT

mkdir -p smac_jepa "$LOG_DIR" "$EVAL_OUT_DIR"

echo "============================================================"
echo "Resume Exp15 and Exp14 to epoch $TARGET_EPOCH, then evaluate"
echo "Repository: $ROOT_DIR"
echo "Logs:       $LOG_DIR"
echo "Started:    $(date)"
echo "============================================================"

# ----------------------------------------------------------------------------
# Install embedded trainer and evaluator.
# ----------------------------------------------------------------------------

