__R2_EVALUATOR_B64__

base64 -d "$TMP_DIR/r2_trainer.py.b64" > "$TMP_DIR/r2_trainer.py"
base64 -d "$TMP_DIR/r2_evaluator.py.b64" > "$TMP_DIR/r2_evaluator.py"

python -m py_compile \
  "$TMP_DIR/r2_trainer.py" \
  "$TMP_DIR/r2_evaluator.py"

install -m 0644 \
  "$TMP_DIR/r2_trainer.py" \
  smac_jepa/train_markov_rollout_rnn_visibility_seqmem_r2offline.py

install -m 0644 \
  "$TMP_DIR/r2_evaluator.py" \
  ./eval_rnn_seqmem_dreamer_probe_r2aware.py

TRAIN_MODULE="smac_jepa.train_markov_rollout_rnn_visibility_seqmem_r2offline"
EVALUATOR="./eval_rnn_seqmem_dreamer_probe_r2aware.py"

LD_LIBRARY_PATH="" python -m "$TRAIN_MODULE" --help >/dev/null
LD_LIBRARY_PATH="" python "$EVALUATOR" --help >/dev/null

echo "Embedded trainer and evaluator installed successfully."

# ----------------------------------------------------------------------------
# Checkpoint helpers.
# ----------------------------------------------------------------------------

select_best_checkpoint() {
  local run_dir="$1"
  local experiment_name="$2"

  python - "$run_dir" "$experiment_name" <<'PY'
from pathlib import Path
import sys
import torch

run_dir = Path(sys.argv[1])
name = sys.argv[2]

candidates = []
if run_dir.exists():
    candidates.extend(run_dir.glob("checkpoint_epoch_*.pt"))
    latest = run_dir / "checkpoint.pt"
    if latest.exists():
        candidates.append(latest)

candidates = sorted(set(path.resolve() for path in candidates))

if not candidates:
    print(
        f"[{name}] ERROR: no checkpoint files found under {run_dir}",
        file=sys.stderr,
    )
    raise SystemExit(1)

valid = []

for path in candidates:
    try:
        try:
            checkpoint = torch.load(
                path,
                map_location="cpu",
                weights_only=False,
            )
        except TypeError:
            checkpoint = torch.load(path, map_location="cpu")

        epoch = int(checkpoint.get("epoch", -1))
        global_step = int(checkpoint.get("global_step", -1))

        if epoch < 0 and path.name.startswith("checkpoint_epoch_"):
            try:
                epoch = int(path.stem.rsplit("_", 1)[-1])
            except ValueError:
                pass

        valid.append(
            (
                epoch,
                global_step,
                path.stat().st_mtime_ns,
                path,
            )
        )

        print(
            f"[{name}] valid checkpoint: "
            f"epoch={epoch} step={global_step} path={path}",
            file=sys.stderr,
        )
    except Exception as exc:
        print(
            f"[{name}] skipped unreadable checkpoint: "
            f"{path} ({type(exc).__name__}: {exc})",
            file=sys.stderr,
        )

if not valid:
    print(
        f"[{name}] ERROR: checkpoint files exist but none are readable",
        file=sys.stderr,
    )
    raise SystemExit(2)

epoch, global_step, _, selected = max(
    valid,
    key=lambda item: (item[0], item[1], item[2]),
)

print(
    f"[{name}] selected checkpoint: "
    f"epoch={epoch} step={global_step} path={selected}",
    file=sys.stderr,
)

print(f"{selected}|{epoch}|{global_step}")
PY
}

validate_target_checkpoint() {
  local checkpoint_path="$1"
  local experiment_name="$2"
  local target_epoch="$3"

  python - "$checkpoint_path" "$experiment_name" "$target_epoch" <<'PY'
from pathlib import Path
import sys
import torch

path = Path(sys.argv[1])
name = sys.argv[2]
target_epoch = int(sys.argv[3])

try:
    try:
        checkpoint = torch.load(
            path,
            map_location="cpu",
            weights_only=False,
        )
    except TypeError:
        checkpoint = torch.load(path, map_location="cpu")
except Exception as exc:
    raise SystemExit(
        f"[{name}] checkpoint is unreadable: {path}: "
        f"{type(exc).__name__}: {exc}"
    )

epoch = int(checkpoint.get("epoch", -1))
global_step = int(checkpoint.get("global_step", -1))

if epoch < target_epoch:
    raise SystemExit(
        f"[{name}] checkpoint has epoch={epoch}, "
        f"expected at least {target_epoch}: {path}"
    )

required = [
    "model_state",
    "memory_module_state",
    "r2_projector_state",
]

missing = [key for key in required if key not in checkpoint]
if missing:
    raise SystemExit(
        f"[{name}] checkpoint lacks required R2 keys {missing}: {path}"
    )

print(
    f"[{name}] verified epoch={epoch} "
    f"global_step={global_step}: {path}"
)
PY
}

run_logged() {
  local name="$1"
  shift

  local log_file="${LOG_DIR}/${name}.log"

  echo
  echo "============================================================"
  echo "START: $name"
  echo "TIME:  $(date)"
  echo "LOG:   $log_file"
  echo "============================================================"

  "$@" 2>&1 | tee "$log_file"
  local code=${PIPESTATUS[0]}

  echo "============================================================"
  echo "END:   $name"
  echo "CODE:  $code"
  echo "TIME:  $(date)"
  echo "============================================================"

  if [[ $code -ne 0 ]]; then
    echo "ERROR: $name failed. Evaluation will not start."
    exit "$code"
  fi
}

# ----------------------------------------------------------------------------
# Training function.
# ----------------------------------------------------------------------------

resume_r2_experiment() {
  local experiment_name="$1"
  local out_dir="$2"
  local wandb_name="$3"
  local use_sigreg="$4"

  local selected=""
  selected="$(select_best_checkpoint "$out_dir" "$experiment_name")"

  local checkpoint_path="${selected%%|*}"
  local remainder="${selected#*|}"
  local saved_epoch="${remainder%%|*}"
  local saved_step="${remainder##*|}"

  echo
  echo "[$experiment_name] latest valid state:"
  echo "  epoch:      $saved_epoch"
  echo "  global step:$saved_step"
  echo "  checkpoint: $checkpoint_path"

  if (( saved_epoch >= TARGET_EPOCH )); then
    echo "[$experiment_name] already reached epoch $TARGET_EPOCH; skipping training."
    return 0
  fi

  local sigreg_args=(--sigreg-weight 0.0)

  if [[ "$use_sigreg" == "true" ]]; then
    sigreg_args=(
      --sigreg-weight 0.01
      --r2-sigreg-divide-by-dim
      --r2-sigreg-knots 17
      --r2-sigreg-num-proj 1024
      --r2-sigreg-proj-chunk 64
      --r2-sigreg-max-samples 0
    )
  fi

  run_logged "train_${experiment_name}_to_epoch_${TARGET_EPOCH}" \
    env LD_LIBRARY_PATH="" python -m "$TRAIN_MODULE" \
      --manifest splits/generated_seed4_mapdims_only.json \
      --split train \
      --out-dir "$out_dir" \
      --model-size default \
      --epochs "$TARGET_EPOCH" \
      --batch-size 16 \
      --num-workers 4 \
      --rollout-window 20 \
      --rollout-horizon 5 \
      --window-mode random \
      --samples-per-epoch 50000 \
      --enemy-visibility-mask \
      --enemy-sight-range 9.0 \
      --temporal-loss lambda \
      --td-lambda 0.9 \
      --r2-dyn-scale 1.0 \
      --r2-rep-scale 0.1 \
      --r2-barlow-scale 0.05 \
      --r2-barlow-lambda 0.0005 \
      --r2-latent-normalize \
      --lr-warmup-steps 1000 \
      "${sigreg_args[@]}" \
      --decoder-weight 0.01 \
      --presence-weight 0.01 \
      --rollout-memory-dim 128 \
      --target-mode full \
      --action-conditioned-memory \
      --one-step-weight 0.5 \
      --resume "$checkpoint_path" \
      --grad-clip 1.0 \
      --device cuda \
      --amp \
      --wandb \
      --wandb-project SMAC-JEPA-losses \
      --wandb-name "$wandb_name"
}

# Preserve the earlier safer ordering: Exp15 first, then Exp14.
resume_r2_experiment \
  "exp15" \
  "$EXP15_DIR" \
  "rnn-seqmem-exp15-r2offline-sigreg-to-e8" \
  "true"

resume_r2_experiment \
  "exp14" \
  "$EXP14_DIR" \
  "rnn-seqmem-exp14-r2offline-to-e8" \
  "false"

# ----------------------------------------------------------------------------
# Resolve and validate the completed epoch-8 checkpoints.
# ----------------------------------------------------------------------------

EXP15_SELECTED="$(select_best_checkpoint "$EXP15_DIR" "Exp15-final")"
EXP14_SELECTED="$(select_best_checkpoint "$EXP14_DIR" "Exp14-final")"

EXP15_CHECKPOINT="${EXP15_SELECTED%%|*}"
EXP14_CHECKPOINT="${EXP14_SELECTED%%|*}"

validate_target_checkpoint \
  "$EXP15_CHECKPOINT" \
  "Exp15" \
  "$TARGET_EPOCH"

validate_target_checkpoint \
  "$EXP14_CHECKPOINT" \
  "Exp14" \
  "$TARGET_EPOCH"

# ----------------------------------------------------------------------------
# Evaluate immediately.
# ----------------------------------------------------------------------------

force_probe_args=()
if [[ "$FORCE_RETRAIN_PROBE" == "1" ]]; then
  force_probe_args+=(--force-retrain-probe)
fi

run_logged "evaluate_exp14_exp15_epoch_${TARGET_EPOCH}" \
  env LD_LIBRARY_PATH="" python "$EVALUATOR" \
    --manifest splits/generated_seed4_mapdims_only.json \
    --split eval \
    --checkpoint "$EXP15_CHECKPOINT" \
    --checkpoint "$EXP14_CHECKPOINT" \
    --out-dir "$EVAL_OUT_DIR" \
    --batch-size "$EVAL_BATCH_SIZE" \
    --num-workers "$EVAL_NUM_WORKERS" \
    --max-batches "$EVAL_MAX_BATCHES" \
    --diagnostics \
    --diagnostic-max-batches "$DIAGNOSTIC_MAX_BATCHES" \
    --eval-rollout-horizon 5 \
    --target-mode full \
    --window-mode sequential \
    --probe-decoder \
    --probe-train-split train \
    --probe-epochs "$PROBE_EPOCHS" \
    --probe-max-batches-per-epoch "$PROBE_MAX_BATCHES" \
    --probe-samples-per-epoch "$PROBE_SAMPLES_PER_EPOCH" \
    --probe-lr 0.001 \
    --probe-weight-decay 0.00001 \
    --probe-seed 123 \
    "${force_probe_args[@]}" \
    --device cuda \
    --amp

echo
echo "============================================================"
echo "TRAINING AND EVALUATION COMPLETE"
echo
echo "Exp15 checkpoint:"
echo "  $EXP15_CHECKPOINT"
echo
echo "Exp14 checkpoint:"
echo "  $EXP14_CHECKPOINT"
echo
echo "Evaluation directory:"
echo "  $EVAL_OUT_DIR"
echo
echo "Main summary:"
echo "  $EVAL_OUT_DIR/eval_seqmem_combined_summary.csv"
echo
echo "Logs:"
echo "  $LOG_DIR"
echo "============================================================"
